from __future__ import print_function
from builtins import object
import smtplib
from email.MIMEMultipart import MIMEMultipart
from email.MIMEText import MIMEText
from email.MIMEBase import MIMEBase
from email import Encoders


class Mailmodule(object):
    """
    Class which has methods to send mails
    """
    def send_mail(self, maillist, subject, body, logpath, filename, from_address):
        """
        This function is used to send mail for each test suite ran.
        Args:
            maillist: List of users for whom the mail should be sent.
            subject: Subject of the mail
            body:
            logpath:
            filename:
            from_address:

        Returns:

        """
        try:
            me = from_address
            msg = MIMEMultipart()
            msg['Subject'] = subject
            msg['From'] = me

            part = MIMEBase('application', "octet-stream")

            part.set_payload(open('{0}'.format(logpath), "rb").read())

            Encoders.encode_base64(part)

            part.add_header('Content-Disposition', 'attachment; filename={0}'.format(filename))

            msg.attach(MIMEText(body))
            msg.attach(part)
            # mumrel002.emea.nsn-intra.net ip = 10.130.128.21
            server = smtplib.SMTP('10.130.128.21')
            for i in maillist:
                msg['To'] = i
                server.sendmail(me, [i], msg.as_string())

        except Exception as e:
            print(e)
            print("EX Mail:", e.message)
        return
